window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f7fa11a1ab9af938"]={"versions": [{"id": "FIG-f7fa11a1ab9af938", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Platzhalter-Diagramm bzw. Dokumenten-Notizblock im Kontext der AUTOSAR-Methodik („Generation of executable code for ECU“). Das Schaubild stellt kein vollständiges Aktivitäts- oder Architekturdiagramm dar, sondern dient als grafischer Vermerk- bzw. Statusspeicher für die noch zu spezifizierende Generierung ausführbaren Codes. Am oberen rechten Rand ist ein Dokumentensymbol angedeutet („modules“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Element ist als Notizfeld bzw. Kommentarblock mit abgeknickter rechter oberer Ecke formatiert. Es enthält zwei Metadaten-Felder:</p>\n<ul class=\"fig-list\">\n<li><code>STATUS</code>: Belegt mit dem Wert <code>proposed</code>.</li>\n<li><code>COMMENT</code>: Belegt mit dem Platzhalter <code>-</code> (kein Kommentar hinterlegt).</li>\n</ul>\n<p class=\"fig-p\">Darüber befindet sich am oberen Rand ein Fragment einer Beschriftung (<code>modules</code>). Weitere Komponenten, Schnittstellen oder Artefakte sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ein Kontroll- oder Datenfluss ist nicht dargestellt. Das Diagramm fungiert als statischer Platzhalter ohne definierte Prozessschritte, Sequenzen oder Verarbeitungslogik für den Build- oder Generierungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt rein informativen bzw. vorläufigen Charakter (<code>STATUS: proposed</code>) und enthält keine normativen Festlegungen, Datentypen oder Schnittstellenvorschriften für die ECU-Code-Generierung. Entwickler und Werkzeuganbieter können aus dieser Fassung keine Implementierungsanforderungen für den Generierungs- oder Build-Workflow ableiten.</p>"}, {"id": "FIG-4c6e51eebd2b472d", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Platzhalter-Diagramm bzw. Dokumenten-Notizblock im Kontext der AUTOSAR-Methodik („Generation of executable code for ECU“). Das Schaubild stellt kein vollständiges Aktivitäts- oder Architekturdiagramm dar, sondern dient als grafischer Vermerk- bzw. Statusspeicher für die noch zu spezifizierende Generierung ausführbaren Codes. Am oberen rechten Rand ist ein Dokumentensymbol angedeutet („modules“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Element ist als Notizfeld bzw. Kommentarblock mit abgeknickter rechter oberer Ecke formatiert. Es enthält zwei Metadaten-Felder:</p>\n<ul class=\"fig-list\">\n<li><code>STATUS</code>: Belegt mit dem Wert <code>proposed</code>.</li>\n<li><code>COMMENT</code>: Belegt mit dem Platzhalter <code>-</code> (kein Kommentar hinterlegt).</li>\n</ul>\n<p class=\"fig-p\">Darüber befindet sich am oberen Rand ein Fragment einer Beschriftung (<code>modules</code>). Weitere Komponenten, Schnittstellen oder Artefakte sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ein Kontroll- oder Datenfluss ist nicht dargestellt. Das Diagramm fungiert als statischer Platzhalter ohne definierte Prozessschritte, Sequenzen oder Verarbeitungslogik für den Build- oder Generierungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt rein informativen bzw. vorläufigen Charakter (<code>STATUS: proposed</code>) und enthält keine normativen Festlegungen, Datentypen oder Schnittstellenvorschriften für die ECU-Code-Generierung. Entwickler und Werkzeuganbieter können aus dieser Fassung keine Implementierungsanforderungen für den Generierungs- oder Build-Workflow ableiten.</p>"}], "trans": [{"from": "FIG-f7fa11a1ab9af938", "to": "FIG-4c6e51eebd2b472d", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4c6e51eebd2b472d", "to": "FIG-f7fa11a1ab9af938", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
